using System.ComponentModel.DataAnnotations;
namespace RentCarManagement.Api.Models;
public sealed record RegisterRequest([Required] string FullName, [Required, EmailAddress] string Email, [Required, MinLength(6)] string Password, string? PhoneNumber, string? DriverLicenseNumber, DateTime? DriverLicenseExpiry);
public sealed record LoginRequest([Required, EmailAddress] string Email, [Required] string Password); public sealed record UpdateProfileRequest([Required] string FullName, string? PhoneNumber, string? DriverLicenseNumber, DateTime? DriverLicenseExpiry);
public sealed record VehicleRequest([Required] string Brand, [Required] string Model, [Range(1900, 2100)] int Year, [Range(0, int.MaxValue)] int Mileage, [Range(0, int.MaxValue)] int MaintenanceMileageThreshold, [Range(0, double.MaxValue)] decimal DailyRate, [Range(0, double.MaxValue)] decimal ExtraKilometerRate, VehicleStatus Status = VehicleStatus.Available);
public sealed record RentalRequest([Range(1, int.MaxValue)] int VehicleId, DateTime ExpectedReturnDate); public sealed record ExtendRentalRequest(DateTime NewExpectedReturnDate); public sealed record ReturnRentalRequest([Range(0, int.MaxValue)] int EndMileage); public sealed record DamageRequest([Required] string Description, [Range(0, double.MaxValue)] decimal Amount); public sealed record TokenResponse(string AccessToken, DateTime ExpiresAt, string Role);
